from sales_dashboard.loader import dedupe_sessions, parse_session_log
from sales_dashboard.metrics import conversion_rate, pooled_conversion_rate
from sales_dashboard.report import campaign_summary


def test_conversion_rate_basic():
    assert conversion_rate([{"converted": True}, {"converted": False}]) == 0.5


def test_conversion_rate_none_counts_as_not_converted():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_dedupe_keeps_last_record_for_duplicate_id():
    events = [
        {"id": "same", "day": 1, "converted": True},
        {"id": "other", "day": 2, "converted": False},
        {"id": "same", "day": 3, "converted": False},
    ]
    assert dedupe_sessions(events) == [
        {"id": "other", "day": 2, "converted": False},
        {"id": "same", "day": 3, "converted": False},
    ]


def test_parse_session_log_skips_blank_and_comment_lines_and_parses_flags():
    assert parse_session_log(["  ", " # comment", " a, 2, ", "b,3,0"]) == [
        {"id": "a", "day": 2, "converted": None},
        {"id": "b", "day": 3, "converted": False},
    ]


def test_parse_session_log_errors_include_original_line_number():
    import pytest

    with pytest.raises(ValueError, match="line 2"):
        parse_session_log(["# skipped", "bad,day,1"])


def test_daily_conversion_counts_inclusive_range():
    from sales_dashboard.loader import daily_conversion_counts

    events = [
        {"id": "a", "day": 1, "converted": True},
        {"id": "b", "day": 2, "converted": False},
        {"id": "c", "day": 3, "converted": True},
        {"id": "d", "day": 4, "converted": True},
    ]
    assert daily_conversion_counts(events, 2, 4) == [0, 1, 1]
    assert daily_conversion_counts(events, 4, 2) == []


def test_campaign_summary_rounds_pooled_rate_and_ignores_empty_groups():
    events = [{"id": "a", "day": 1, "converted": True}, {"id": "b", "day": 1, "converted": False},
              {"id": "c", "day": 2, "converted": False}]
    result = campaign_summary({"z": [], "g": events}, 1)
    assert result == {"rate": 0.333, "recent": 0, "groups": 1}


def test_group_rate_order_empty_groups_top_order_and_streak():
    from sales_dashboard.metrics import conversion_rate_by_group, longest_conversion_streak
    from sales_dashboard.report import top_converting_groups

    groups = {"z": [{"converted": True}], "empty": [], "a": [{"converted": True}]}
    assert list(conversion_rate_by_group(groups)) == ["a", "empty", "z"]
    assert conversion_rate_by_group(groups)["empty"] is None
    assert top_converting_groups(groups, 5) == ["a", "z"]
    assert longest_conversion_streak([2, 1, 0, -1, 3]) == 2


def test_conversions_in_window_uses_exactly_days_entries():
    from sales_dashboard.metrics import conversions_in_window

    assert conversions_in_window([1, 2, 3], 2) == 5
    assert conversions_in_window([1, 2, 3], 0) == 0
    assert conversions_in_window([1, 2, 3], 5) == 6


def test_pooled_rate_weights_each_session_not_each_group():
    groups = {"large": [{"converted": True}] + [{"converted": False}] * 9,
              "small": [{"converted": True}]}
    assert pooled_conversion_rate(groups) == 2 / 11
    assert pooled_conversion_rate({"empty": []}) == 0.0


def test_pooled_conversion_rate_equal_groups():
    groups = {"a": [{"converted": True}, {"converted": False}], "b": [{"converted": True}, {"converted": False}]}
    assert pooled_conversion_rate(groups) == 0.5


def test_parse_session_log_one_line():
    assert parse_session_log(["x1,3,1"]) == [{"id": "x1", "day": 3, "converted": True}]


def test_campaign_summary_basic():
    e = [{"id": "a", "day": 1, "converted": True}, {"id": "b", "day": 2, "converted": False}]
    assert campaign_summary({"g": e}, 1)["groups"] == 1

